160	        validateRequiredFields(ownerFieldsDto);
161	        HttpHeaders headers = new HttpHeaders();
162	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
163	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
164	        owner.setRegistrationDate(registrationDate);
165	        requireDailyCapacity(registrationDate);
166	        requireCityHasCapacity(owner.getCity());
167	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
168	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
169	            joinHousehold(owner);
170	        } else {
171	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
172	        }
173	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
174	        requireUniqueTelephone(telephone);
175	        owner.setTelephone(telephone);
176	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
177	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
178	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
179	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
180	        this.clinicService.saveOwner(owner);
181	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
182	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
183	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
184	        headers.setLocation(UriComponentsBuilder.newInstance()
185	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
