206	    /**
207	     * Counts the existing owners whose registration date equals the given business-day date. This is
208	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
209	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
210	     * the bulk-signup warning.
211	     *
212	     * @param registrationDate the effective business-day registration date to count against
213	     * @return the number of pre-existing owners registered on that date
214	     */
215	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
216	        return this.clinicService.findAllOwners().stream()
217	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
218	            .count();
219	    }
