239	    /**
240	     * Generates the customer code for a newly created owner, formatted
241	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
242	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
243	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
244	     * that city (e.g. {@code 'LON-SMI-0007'}).
245	     *
246	     * @param city the owner's city
247	     * @param lastName the owner's last name
248	     * @return the generated customer code
249	     */
250	    private String generateCustomerCode(String city, String lastName) {
251	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
252	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
253	        int sequence = (int) this.clinicService.findAllOwners().stream()
254	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
255	            .count() + 1;
256	        return String.format("%s-%s-%04d", city3, last3, sequence);
257	    }
