264	     * @param firstName the first name of the owner being created
265	     * @param lastName the last name of the owner being created
266	     * @return the number of pre-existing namesakes
267	     */
268	    private int countNamesakes(String firstName, String lastName) {
269	        return (int) this.clinicService.findAllOwners().stream()
270	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
271	                && equalsIgnoreCase(existing.getLastName(), lastName))
272	            .count();
