275	    /**
276	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
277	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
278	     *
279	     * @param a the first value, possibly {@code null}
280	     * @param b the second value, possibly {@code null}
281	     * @return whether the values are equal ignoring case
282	     */
283	    private boolean equalsIgnoreCase(String a, String b) {
284	        return a == null ? b == null : a.equalsIgnoreCase(b);
285	    }
