318	    /**
319	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
320	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
321	     * what gets stored and returned.
322	     *
323	     * @param telephone the raw telephone value from the request
324	     * @return the normalized E.164 telephone number
325	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
326	     */
327	    private String normalizeTelephone(String telephone) {
328	        String e164 = toE164(telephone);
329	        if (e164 == null) {
330	            throw new InvalidOwnerFieldsException(List.of("telephone"));
331	        }
332	        return e164;
333	    }
334	
335	    /**
336	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
337	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
338	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
339	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
340	     * it contains 8 to 15 digits after the {@code '+'}.
341	     *
342	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
343	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
344	     *
345	     * @param telephone the raw telephone value, possibly {@code null}
346	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
347	     */
348	    private String toE164(String telephone) {
349	        if (telephone == null) {
350	            return null;
351	        }
352	        String cleaned = telephone.replaceAll("[ \\-()]", "");
353	        String digits;
354	        if (cleaned.startsWith("+")) {
355	            digits = cleaned.substring(1);
356	        } else {
357	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
358	            digits = "61" + national;
359	        }
360	        if (!digits.matches("[0-9]{8,15}")) {
361	            return null;
362	        }
363	        return "+" + digits;
364	    }
365	
366	    /**
367	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
368	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
369	     * and returned lower-cased.
370	     *
371	     * @param email the raw email value from the request, possibly {@code null}
372	     * @return the lower-cased email, or {@code null} when none was supplied
373	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
374	     */
375	    private String normalizeEmail(String email) {
376	        if (!StringUtils.hasText(email)) {
377	            return null;
378	        }
379	        String trimmed = email.trim();
380	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
381	            throw new InvalidOwnerFieldsException(List.of("email"));
382	        }
383	        return trimmed.toLowerCase(Locale.ROOT);
384	    }
