386	    /**
387	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
388	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
389	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
390	     *
391	     * @param telephone the normalized (E.164) telephone of the owner being created
392	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
393	     */
394	    private void requireUniqueTelephone(String telephone) {
395	        boolean inUse = this.clinicService.findAllOwners().stream()
396	            .map(Owner::getTelephone)
397	            .filter(existing -> existing != null)
398	            .map(existing -> {
399	                String e164 = toE164(existing);
400	                return e164 != null ? e164 : existing;
401	            })
402	            .anyMatch(telephone::equals);
403	        if (inUse) {
404	            throw new DuplicateTelephoneException(telephone);
405	        }
406	    }
