408	    /**
409	     * Rejects an owner whose last name and address match those of an existing owner, where both are
410	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
411	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
412	     *
413	     * @param lastName the last name of the owner being created
414	     * @param address the address of the owner being created
415	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
416	     */
417	    private void requireUniqueHousehold(String lastName, String address) {
418	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
419	            throw new DuplicateHouseholdException(lastName, address);
420	        }
421	    }
422	
423	    /**
424	     * Returns the existing owners that belong to the same household as the given last name and
425	     * address, i.e. those whose last name and address match case-insensitively and with runs of
426	     * whitespace collapsed to a single space.
427	     *
428	     * @param lastName the last name to match
429	     * @param address the address to match
430	     * @return the matching owners (possibly empty, never {@code null})
431	     */
432	    private List<Owner> findHouseholdMembers(String lastName, String address) {
433	        String normalizedLastName = normalizeForHousehold(lastName);
434	        String normalizedAddress = normalizeAddress(address);
435	        return this.clinicService.findAllOwners().stream()
436	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
437	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
438	            .toList();
439	    }
440	
441	    /**
442	     * Joins the owner being created to the shared household of any existing owner(s) that have the
443	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
444	     * member of the household - the existing owners and the new one - is assigned the same stable
445	     * {@code householdId}, so the shared identifier can be read back from any of them.
446	     *
447	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
448	     * the owner is left without a {@code householdId}.
449	     *
450	     * <p>Every member of the household - the existing owners and the new one - is also stamped with
451	     * the household's member count after this create ({@code householdSize}), so the shared size can
452	     * be read back from any of them and drives the {@code GOLD} membership tier (3 or more members).
453	     *
454	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
455	     */
456	    private void joinHousehold(Owner owner) {
457	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
458	        if (members.isEmpty()) {
459	            return;
460	        }
461	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
462	        int householdSize = members.size() + 1;
463	        owner.setHouseholdId(householdId);
464	        owner.setHouseholdSize(householdSize);
465	        for (Owner member : members) {
466	            member.setHouseholdId(householdId);
467	            member.setHouseholdSize(householdSize);
468	            this.clinicService.saveOwner(member);
469	        }
470	    }
471	
472	    /**
473	     * Computes the stable, shared household identifier for a last name and address. The value is
474	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
475	     * name and address, so every owner in the same household computes the same identifier.
476	     *
477	     * @param lastName the last name of the household
478	     * @param address the address of the household
479	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
480	     */
481	    private String computeHouseholdId(String lastName, String address) {
482	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
483	        try {
484	            byte[] digest = MessageDigest.getInstance("SHA-256")
485	                .digest(key.getBytes(StandardCharsets.UTF_8));
486	            StringBuilder hex = new StringBuilder();
487	            for (int i = 0; i < 6; i++) {
488	                hex.append(String.format("%02X", digest[i]));
489	            }
490	            return "HH-" + hex;
491	        } catch (NoSuchAlgorithmException e) {
492	            throw new IllegalStateException("SHA-256 algorithm not available", e);
493	        }
494	    }
495	
496	    /**
497	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
498	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
499	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
500	     *
501	     * @param value the raw value, possibly {@code null}
502	     * @return the normalized value
503	     */
504	    private String normalizeForHousehold(String value) {
505	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
506	    }
507	
508	    /**
509	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
510	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
511	     * value yields an empty string.
512	     *
513	     * @param value the raw value, possibly {@code null}
514	     * @return the trimmed, whitespace-collapsed value
515	     */
516	    private String collapseWhitespace(String value) {
517	        if (value == null) {
518	            return "";
519	        }
520	        return value.trim().replaceAll("\\s+", " ");
521	    }
522	
523	    /**
524	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
525	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
526	     * is upper-cased, and common street-type abbreviations are expanded as whole words
527	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
528	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
529	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
530	     *
531	     * @param address the raw address value, possibly {@code null}
532	     * @return the normalized address
533	     */
534	    private String normalizeAddress(String address) {
535	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
536	        if (collapsed.isEmpty()) {
537	            return "";
538	        }
539	        String[] tokens = collapsed.split(" ");
540	        StringBuilder normalized = new StringBuilder();
541	        for (int i = 0; i < tokens.length; i++) {
542	            if (i > 0) {
543	                normalized.append(' ');
544	            }
545	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
546	        }
547	        return normalized.toString();
548	    }
